#: Nautilus bar aggregation -> the bridge's timeframe name, and the bar's
#: length in seconds. The seconds matter: **`ts_event` on a Nautilus bar is
#: the bar's close**, and MT5 stamps a bar with its open, so one has to be
#: converted into the other. Getting it backwards does not shift a series
#: feeding `statespace` - it silences it, because `observe_bar` refuses a bar
#: whose time is not strictly after the last one.
TIMEFRAMES: dict[str, tuple[str, float]] = {
    "1-MINUTE": ("M1", 60.0),
    "5-MINUTE": ("M5", 300.0),
    "15-MINUTE": ("M15", 900.0),
    "30-MINUTE": ("M30", 1800.0),
    "1-HOUR": ("H1", 3600.0),
    "4-HOUR": ("H4", 14400.0),
    "1-DAY": ("D1", 86400.0),
}


#: Where live quotes come from.
#:
#: - `poll`: ask for the current tick every `poll_seconds`. A **sample**: two
#:   ticks inside one interval arrive as the later of them.
#: - `ticks`: ask for every tick since the last one seen (`copy_ticks_range`).
#:   **Complete, not instant** - nothing is lost, and the latest arrives up to
#:   one interval late. Needs no change to the terminal.
#: - `push`: the transport hands over ticks as the terminal produces them
#:   (an Expert Advisor's `OnTick`, relayed by the bridge). Complete and
#:   immediate, and only available where the transport has a `stream`.
QUOTE_SOURCES: tuple[str, ...] = ("poll", "ticks", "push")

#: How long a subscribed feed may produce nothing before it is reported, and
#: how often after that. 90 seconds because the bar loop sleeps `seconds / 10`
#: - 90s on a 15-minute bar - so a shorter grace would report a feed that is
#: merely between polls.
WATCHDOG_GRACE = 90.0
WATCHDOG_EVERY = 300.0


def feed_reading(feeds: int, counts: dict[str, int]) -> tuple[str | None, bool]:
    """What to say about the feeds, and whether it is a fault.

    Separate from the logging because the **wording is the diagnostic**. A
    reader gets one line, and "nothing published" sends them to the market
    while "no poll has run at all" sends them to the tasks - which on
    2026-11-04 is where the fault was. The Cython `Logger` has read-only
    attributes, so a test cannot capture a log call; it can assert this.

    `None` means there is nothing to report: no subscriptions, so no feed can
    be late.
    """
    if feeds <= 0:
        return None, False
    reading = " ".join(f"{name}={value}" for name, value in counts.items())
    if counts.get("quotes") or counts.get("bars"):
        return f"feeds: {feeds} subscribed, {reading}", False
    if not counts.get("quote_polls") and not counts.get("bar_polls"):
        why = (
            "No poll has run at all, so the tasks were created and are not "
            "executing - this is not a quiet market."
        )
    else:
        why = "The polls are running, so the bridge or the parse is giving nothing back."
    return f"{feeds} feeds subscribed and nothing published: {reading}. {why}", True


def _milliseconds(row: dict) -> int | None:
    """A tick's time in epoch milliseconds, whichever way the transport spelled it.

    rpyc returns MT5's own integers. The HTTP bridge runs the same rows through
    `pandas.to_datetime`, so `time_msc` arrives as an ISO string and `time` as
    one too - the same tick in two shapes. A naive string is UTC, which is how
    pandas produced it from an epoch.
    """
    for key, scale in (("time_msc", 1), ("time", 1000)):
        value = row.get(key)
        if value in (None, ""):
            continue
        if isinstance(value, datetime):
            value = value if value.tzinfo else value.replace(tzinfo=UTC)
            return int(value.timestamp() * 1000)
        if isinstance(value, str):
            try:
                parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                continue
            parsed = parsed if parsed.tzinfo else parsed.replace(tzinfo=UTC)
            return int(parsed.timestamp() * 1000)
        try:
            return int(float(value) * scale)
        except (TypeError, ValueError):
            continue
    return None


def _bar_seconds(row: dict) -> float:
    """A bar's open time in epoch seconds, whichever way the bridge spelled it.

    **`_milliseconds` already knew this and the bar path did not use it.** The
    HTTP bridge runs its rows through `pandas.to_datetime`, so `time` arrives
    as an ISO string, and both bar sites did a bare numeric conversion on it:
    the poll loop `int(row.get("time") or 0)` and `_bar` `float(...)`. Against
    the live bridge every bar poll raised `invalid literal for int() with base
    10: '2026-11-...'`, on all six symbols, continuously - so the desk held
    quotes and **never received a bar**, which is every strategy's only input.

    The tick path was correct because it went through `_milliseconds`. The
    knowledge was in the file; this makes the bar path use it.

    Zero on an unparseable row rather than a raise: the caller treats a
    non-advancing timestamp as "nothing new", which is the safe reading, and a
    raise here would lose the other bar in the same response.
    """
    found = _milliseconds(row)
    return found / 1000.0 if found is not None else 0.0


